    "import pandas as pd\n",
    "from xgboost import XGBRegressor\n",
    "\n",
    "xgr_model = XGBRegressor()\n",
    "xgr_model.fit(X_train, y_train)\n",
    "\n",
    "feature_names = X_train.columns\n",
    "\n",
    "new_data = pd.DataFrame([{\n",
    "    'bedrooms': 3,\n",
    "    'bathrooms': 2,\n",
    "    'sqft_living': 1300,\n",
    "    'sqft_lot': 5000,\n",
